// STACK FRAME LIFECYCLE (LIFO)

int nested_call(int param_A) {
    // FRAME 2 PUSHED
    // 1. ARGUMENT: param_A (input)
    int local_B = 10;
    // 2. LOCAL VAR: local_B
    return param_A + local_B;
    // 3. RETURN ADDR: Used; FRAME 2 POPPED
}

void caller_function(int start_val) {
    // FRAME 1 PUSHED
    int current_state = start_val * 2;
    int result = nested_call(current_state);
    // FRAME 1 context (saved registers, locals) restored
}
// FRAME 1 POPPED upon return
